const d = $json;
const idEmpresa = String(d.id_empresa || '').trim();
const empresaValida = idEmpresa.length > 0;

return [{ json: {
  id_empresa: idEmpresa,
  empresa_valida: empresaValida,
  evento_resultado: empresaValida ? '' : 'ERRO_COBRANCA',
  erro: empresaValida ? '' : 'id_empresa é obrigatório e não pode ser vazio para executar a cobrança automática (nunca fazer busca multi-tenant sem ID_EMPRESA).'
} }];

const d = $json;
const agora = DateTime.now().setZone('America/Sao_Paulo');
const hora = agora.hour + agora.minute / 60;
const dentroDoHorario = hora >= 9 && hora < 18;

return [{ json: {
  ...d,
  dentro_do_horario: dentroDoHorario,
  hora_atual_sp: agora.toFormat('HH:mm'),
  agora_iso: agora.toISO(),
  evento_resultado: dentroDoHorario ? '' : 'FORA_HORARIO_COBRANCA',
  erro: dentroDoHorario ? '' : `Fora da janela permitida para cobrança automática (09:00-18:00, America/Sao_Paulo). Horário atual: ${agora.toFormat('HH:mm')}.`
} }];

const ctx = $('CODE - Validar Horário Permitido').first().json;
const idEmpresa = ctx.id_empresa;
const phoneNumberId = ctx.phone_number_id || '';

const pagRaw = $items('GS - Buscar Pagamentos Da Empresa').map(i => i.json);
const cobRaw = $items('GS - Buscar Cobranças Existentes').map(i => i.json);
const cliRaw = $items('GS - Buscar Clientes').map(i => i.json);

// Detecta falha técnica explicitamente pelo campo error de cada item (nunca por
// contagem de itens: alwaysOutputData:true garante >=1 item mesmo em falha técnica,
// então "0 itens" nunca é um sinal confiável - o mesmo bug já confirmado nos WF008/09/10).
const erroPag = pagRaw.find(r => r && r.error);
const erroCob = cobRaw.find(r => r && r.error);
const erroCli = cliRaw.find(r => r && r.error);
const itemComErro = erroPag || erroCob || erroCli;

if (itemComErro) {
  const origemErro = erroPag ? 'PAGAMENTOS' : (erroCob ? 'COBRANCAS' : 'CLIENTES');
  const err = itemComErro.error || {};
  return [{ json: {
    id_empresa: idEmpresa, id_pagamento: '', id_agendamento: '', id_cliente: '',
    telefone_cliente: '', nome_cliente: '', phone_number_id: phoneNumberId,
    valor_pendente: 0, tentativa: 0, precisa_enviar: false, cobranca_enviada: false,
    origem: 'AUTOMATICO',
    evento_resultado: 'ERRO_COBRANCA',
    erro: `Falha técnica ao consultar ${origemErro} no Google Sheets: ${String((err && err.message) || err || 'erro desconhecido')}`
  } }];
}

const pagamentosTodos = pagRaw.filter(r => r && r.ID_PAGAMENTO);
const cobrancas = cobRaw.filter(r => r && r.ID_COBRANCA);
const clientes = cliRaw.filter(r => r && r.ID_CLIENTE);

if (pagamentosTodos.length === 0) {
  return [{ json: {
    id_empresa: idEmpresa, id_pagamento: '', id_agendamento: '', id_cliente: '',
    telefone_cliente: '', nome_cliente: '', phone_number_id: phoneNumberId,
    valor_pendente: 0, tentativa: 0, precisa_enviar: false, cobranca_enviada: false,
    origem: 'AUTOMATICO',
    evento_resultado: 'PAGAMENTO_NAO_ENCONTRADO',
    erro: 'Nenhum registro em PAGAMENTOS encontrado para esta empresa.'
  } }];
}

// PAGAMENTOS é transacional: cada parcela gera uma nova linha e as linhas antigas
// permanecem com STATUS=PARCIAL mesmo depois de o agendamento ser totalmente quitado
// (ex.: PARCIAL 60 -> PARCIAL 30 -> PAGO 0). Por isso a busca (GS - Buscar Pagamentos Da
// Empresa) não filtra mais por STATUS - agrupamos por ID_AGENDAMENTO e consideramos
// SOMENTE o registro mais recente (por DATA_HORA) como o estado financeiro atual de cada
// agendamento, nunca cada linha histórica como uma dívida independente.
const porAgendamento = new Map();
for (const pag of pagamentosTodos) {
  const chave = `${pag.ID_EMPRESA || idEmpresa}::${pag.ID_AGENDAMENTO || ('__SEM_AGENDAMENTO_' + pag.ID_PAGAMENTO)}`;
  const dt = DateTime.fromISO(String(pag.DATA_HORA || ''), { zone: 'America/Sao_Paulo' });
  const atual = porAgendamento.get(chave);
  const atualDt = atual ? atual._dt : null;
  const maisRecente = !atual || (dt.isValid && (!atualDt || !atualDt.isValid || dt > atualDt));
  if (maisRecente) {
    porAgendamento.set(chave, { ...pag, _dt: dt });
  }
}

const agora = ctx.agora_iso ? DateTime.fromISO(ctx.agora_iso, { zone: 'America/Sao_Paulo' }) : DateTime.now().setZone('America/Sao_Paulo');

const resultados = [];

// Map.values() preserva no máximo 1 estado por ID_AGENDAMENTO -> no máximo 1 item de
// cobrança por agendamento nesta execução, por construção.
for (const estadoAtual of porAgendamento.values()) {
  const idPagamento = estadoAtual.ID_PAGAMENTO;
  const idAgendamento = estadoAtual.ID_AGENDAMENTO || '';
  const valorPendente = Number(estadoAtual.VALOR_PENDENTE);
  const status = String(estadoAtual.STATUS || '').toUpperCase();
  const cliente = clientes.find(c => String(c.ID_CLIENTE) === String(estadoAtual.ID_CLIENTE)) || null;

  const base = {
    id_empresa: idEmpresa,
    id_pagamento: idPagamento,
    id_agendamento: idAgendamento,
    id_cliente: estadoAtual.ID_CLIENTE || '',
    telefone_cliente: cliente ? String(cliente.TELEFONE || '').replace(/\D/g, '') : '',
    nome_cliente: cliente ? (cliente.NOME || '') : '',
    phone_number_id: phoneNumberId,
    valor_pendente: isNaN(valorPendente) ? 0 : valorPendente,
    origem: 'AUTOMATICO'
  };

  // Estado mais recente já quitado (STATUS=PAGO) ou sem saldo pendente: nunca cobrar.
  if (status === 'PAGO' || !(base.valor_pendente > 0)) {
    resultados.push({ ...base, precisa_enviar: false, cobranca_enviada: false, tentativa: 0, evento_resultado: 'PAGAMENTO_JA_QUITADO', erro: 'Este agendamento já está quitado (estado financeiro mais recente é PAGO ou VALOR_PENDENTE<=0).' });
    continue;
  }

  // Defensivo: estado mais recente não é PAGO nem PARCIAL com saldo (dado inconsistente).
  if (status !== 'PARCIAL') {
    resultados.push({ ...base, precisa_enviar: false, cobranca_enviada: false, tentativa: 0, evento_resultado: 'VALOR_PENDENTE_INVALIDO', erro: `Estado financeiro mais recente tem STATUS="${estadoAtual.STATUS}" inesperado (nem PAGO nem PARCIAL); cobrança bloqueada por segurança.` });
    continue;
  }

  // Histórico de cobranças controlado por ID_AGENDAMENTO (não por ID_PAGAMENTO): como cada
  // parcela gera um novo ID_PAGAMENTO, controlar por ID_PAGAMENTO reiniciaria indevidamente
  // a janela de 24h e o limite de 3 tentativas a cada novo pagamento parcial do mesmo
  // agendamento. COBRANCAS já possui a coluna ID_AGENDAMENTO (ver GS - Registrar Cobrança).
  const historico = cobrancas
    .filter(c => String(c.ID_AGENDAMENTO) === String(idAgendamento))
    .map(c => ({ ...c, _dt: DateTime.fromISO(String(c.DATA_HORA || ''), { zone: 'America/Sao_Paulo' }) }))
    .filter(c => c._dt.isValid)
    .sort((a, b) => b._dt.toMillis() - a._dt.toMillis());

  const tentativasAnteriores = historico.length;
  const ultimaTentativa = historico[0] || null;

  if (tentativasAnteriores >= 3) {
    resultados.push({ ...base, precisa_enviar: false, cobranca_enviada: false, tentativa: tentativasAnteriores, evento_resultado: 'LIMITE_COBRANCAS_ATINGIDO', erro: `Limite de 3 cobranças automáticas já atingido para este agendamento (${tentativasAnteriores} tentativas registradas em COBRANCAS).` });
    continue;
  }

  if (ultimaTentativa) {
    const horasDesdeUltima = agora.diff(ultimaTentativa._dt, 'hours').hours;
    if (horasDesdeUltima < 24) {
      resultados.push({ ...base, precisa_enviar: false, cobranca_enviada: false, tentativa: tentativasAnteriores, evento_resultado: 'COBRANCA_RECENTE', erro: `Já existe uma cobrança automática enviada nas últimas 24 horas para este agendamento (há ${horasDesdeUltima.toFixed(1)}h).` });
      continue;
    }
  }

  const valorFormatado = base.valor_pendente.toFixed(2).replace('.', ',');
  const nomeExibicao = base.nome_cliente && base.nome_cliente.trim() ? base.nome_cliente.trim() : 'Cliente';
  const mensagem = `Olá, ${nomeExibicao}! Identificamos que ainda existe um saldo de R$ ${valorFormatado} referente ao seu atendimento. Caso o pagamento já tenha sido realizado, por favor desconsidere esta mensagem.`;

  resultados.push({
    ...base,
    precisa_enviar: true,
    cobranca_enviada: false,
    tentativa: tentativasAnteriores + 1,
    resposta_cliente: mensagem
  });
}

return resultados.map(r => ({ json: r }));

const envio = $json; // resposta de EXEC - WF012 Comunicação para ESTA cobrança

// Roda em modo "Run Once for Each Item" propositalmente: no modo padrão ("Run Once for
// All Items"), $json equivaleria sempre ao primeiro item e este node só devolveria 1
// resultado mesmo recebendo várias cobranças elegíveis na mesma execução - as demais
// seriam descartadas silenciosamente. Rodar por item garante que cada cobrança seja
// processada E que o n8n mantenha o pairedItem correto por item, necessário para
// CODE - Erro Registro Cobrança localizar a cobrança certa via itemMatching() se o
// registro em COBRANCAS falhar.
//
// NÃO usar $('CODE - Avaliar Cobranças Elegíveis').item/.first() aqui: pairedItem não
// atravessa de forma confiável o limite de um Execute Workflow (bug real confirmado no
// WF013). A correção é usar somente os campos que o próprio WF012 já ecoa de volta em
// $json (id_empresa/id_cliente/id_agendamento/telefone_cliente/nome_cliente/
// phone_number_id/origem/resposta_cliente) e o pacote dados, que WF011 já envia com
// id_pagamento/tentativa/valor_pendente.
const pacote = envio.dados || {};
const cobranca = {
  id_empresa: envio.id_empresa,
  id_pagamento: pacote.id_pagamento || '',
  id_agendamento: envio.id_agendamento,
  id_cliente: envio.id_cliente,
  telefone_cliente: envio.telefone_cliente,
  nome_cliente: envio.nome_cliente,
  phone_number_id: envio.phone_number_id,
  valor_pendente: pacote.valor_pendente,
  tentativa: pacote.tentativa,
  resposta_cliente: envio.resposta_cliente,
  origem: envio.origem
};

const enviado = envio.enviado === true;
const agora = DateTime.now().setZone('America/Sao_Paulo').toISO();
const idCobranca = `COB${Date.now()}${Math.random().toString(36).slice(2, 8)}`;

return { json: {
  ...cobranca,
  ID_COBRANCA: idCobranca,
  ID_EMPRESA: cobranca.id_empresa,
  ID_PAGAMENTO: cobranca.id_pagamento,
  ID_AGENDAMENTO: cobranca.id_agendamento,
  ID_CLIENTE: cobranca.id_cliente,
  TELEFONE: cobranca.telefone_cliente,
  VALOR_PENDENTE: cobranca.valor_pendente,
  TENTATIVA: cobranca.tentativa,
  STATUS: enviado ? 'ENVIADA' : 'FALHA',
  DATA_HORA: agora,
  WHATSAPP_MESSAGE_ID: envio.whatsapp_message_id || '',
  OBSERVACOES: enviado ? '' : String(envio.erro || 'Falha ao enviar cobrança via WF012.'),
  cobranca_enviada: enviado,
  status_cobranca: enviado ? 'ENVIADA' : 'FALHA_ENVIO',
  evento_resultado: enviado ? 'COBRANCA_ENVIADA' : 'ERRO_COBRANCA',
  erro: enviado ? '' : String(envio.erro || 'Falha ao enviar cobrança via WF012.')
} };

const envio = $json; // saída de erro de GS - Registrar Cobrança: confirmado em teste
// real no n8n Cloud que contém APENAS {"error": "..."} - nenhum outro campo sobrevive
// à falha do node.
//
// NÃO usar $('CODE - Processar Resultado Envio').item (inferência automática de
// pairedItem): confirmado por teste real que retorna dados errados/undefined na saída
// de erro deste node. NÃO usar .first() (pegaria sempre a primeira cobrança da
// execução, misturando dados quando há 2+ cobranças elegíveis em paralelo). A forma
// correta é itemMatching($itemIndex): usa o índice explícito deste item (dentro da
// própria lista de erros que chegou a este node) para percorrer a cadeia real de
// pairedItem até a cobrança de origem exata - funciona de forma confiável porque
// CODE - Processar Resultado Envio agora roda uma vez por item ("Run Once for Each
// Item", mesma correção), preservando o pairedItem corretamente item a item.
const cobranca = $('CODE - Processar Resultado Envio').itemMatching($itemIndex).json;
const err = envio.error || {};

return { json: {
  id_empresa: cobranca.id_empresa,
  id_pagamento: cobranca.id_pagamento,
  id_agendamento: cobranca.id_agendamento,
  id_cliente: cobranca.id_cliente,
  valor_pendente: cobranca.valor_pendente,
  cobranca_enviada: cobranca.cobranca_enviada,
  tentativa: cobranca.tentativa,
  status_cobranca: cobranca.status_cobranca,
  resposta_cliente: cobranca.resposta_cliente,
  origem: cobranca.origem,
  evento_resultado: 'ERRO_COBRANCA',
  erro: `Cobrança processada (enviada=${cobranca.cobranca_enviada}) mas falhou ao registrar em COBRANCAS: ${String((err && err.message) || err || 'erro desconhecido')}`
} };

const ctx = $('CODE - Validar Empresa').first().json;

// Detecta falha técnica pelo campo error do item (nunca por contagem de itens:
// alwaysOutputData:true garante >=1 item mesmo em erro técnico, o mesmo bug ja
// confirmado nos WF008/WF009/WF010).
const itensBusca = $items('GS - Buscar Empresa').map(i => i.json);
const itemComErro = itensBusca.find(r => r && r.error);
if (itemComErro) {
  const err = itemComErro.error || {};
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '',
    evento_resultado: 'ERRO_COBRANCA',
    erro: `Falha técnica ao consultar EMPRESAS no Google Sheets: ${String((err && err.message) || err || 'erro desconhecido')}`
  } }];
}

const rows = itensBusca.filter(r => r && r.ID_EMPRESA);

if (rows.length === 0) {
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '',
    evento_resultado: 'EMPRESA_NAO_ENCONTRADA',
    erro: 'Empresa não encontrada na aba EMPRESAS para o id_empresa informado.'
  } }];
}

const empresa = rows[0];
const phoneNumberId = String(empresa.WHATSAPP_PHONE_NUMBER_ID || '').trim();

if (!phoneNumberId) {
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '',
    evento_resultado: 'WHATSAPP_NAO_CONFIGURADO',
    erro: 'WHATSAPP_PHONE_NUMBER_ID não está configurado para esta empresa em EMPRESAS.'
  } }];
}

return [{ json: {
  ...ctx, pode_prosseguir: true, phone_number_id: phoneNumberId, evento_resultado: ''
} }];
